UPDATE workflow_node_execution
SET status=#{status}, display_output=#{displayOutput}, output_json=#{outputJson},
    prompt_tokens=#{promptTokens}, candidate_tokens=#{candidateTokens}, total_tokens=#{totalTokens},
    error_code=#{errorCode}, error_message=#{errorMessage}, finished_at=#{finishedAt}
WHERE tenant_id=#{tenantId} AND run_id=#{runId} AND node_execution_id=#{nodeExecutionId}
  AND trace_id=#{traceId} AND deleted=0

UPDATE workflow_node_execution
SET status='CANCELLED', error_code='RUN_CANCELLED', error_message='运行已取消', finished_at=#{finishedAt}
WHERE tenant_id=#{tenantId} AND run_id=#{runId} AND status='RUNNING' AND deleted=0
